def family_init(ctx):
    import math
    bars = ctx.bars
    n = len(bars)
    c = [float(b["c"]) for b in bars]
    m = max(1, int(ctx.p.lag))
    N = max(20, int(ctx.p.n_samp))
    rw = max(10, int(ctx.p.r_win))

    r = [0.0] * n
    for i in range(1, n):
        if c[i] > 0.0 and c[i - 1] > 0.0:
            r[i] = math.log(c[i] / c[i - 1])

    ps = [0.0] * (n + 1)
    p2 = [0.0] * (n + 1)
    for i in range(n):
        ps[i + 1] = ps[i] + r[i]
        p2[i + 1] = p2[i] + r[i] * r[i]
    sd = [None] * n
    for i in range(n):
        if i + 1 < rw:
            continue
        mu = (ps[i + 1] - ps[i + 1 - rw]) / rw
        var = (p2[i + 1] - p2[i + 1 - rw]) / rw - mu * mu
        if var > 0.0:
            sd[i] = math.sqrt(var)

    # the sign-pair sequence: only bars with a non-zero return at BOTH ends
    match = []
    midx = []
    for i in range(m, n):
        if r[i] != 0.0 and r[i - m] != 0.0:
            match.append(1 if (r[i] > 0.0) == (r[i - m] > 0.0) else 0)
            midx.append(i)
    cps = [0] * (len(match) + 1)
    for k in range(len(match)):
        cps[k + 1] = cps[k] + match[k]

    z = [None] * n
    root = math.sqrt(float(N))
    for k in range(len(match)):
        if k + 1 < N:
            continue
        p = (cps[k + 1] - cps[k + 1 - N]) / float(N)
        z[midx[k]] = (2.0 * p - 1.0) * root

    ctx.z = ctx.series(z, "z_sign")
    ctx.r = ctx.series(r, "ret")
    ctx.sd = ctx.series(sd, "ret_sd")


def signal(ctx, i):
    z = ctx.z[i]
    if z is None:
        return 0
    r = ctx.r[i]
    if r == 0.0:
        return 0
    s = ctx.sd[i]
    if s is None or s <= 0.0:
        return 0
    if abs(r) < float(ctx.p.r_min) * s:
        return 0
    thr = float(ctx.p.z_thr)
    d = 1 if r > 0.0 else -1
    if z <= -thr:
        return -d
    if z >= thr:
        return d
    return 0


def exit_signal(ctx, i):
    """Held exactly `lag` bars -- the horizon the statistic was measured over."""
    if not ctx.positions:
        return False
    e = min(p["entry_i"] for p in ctx.positions)
    return (i - e) >= max(1, int(ctx.p.lag))
